    return CheckResult("s5_report", ok, f"{len(kept)} kept changes, {commits} commits since v0",
                       relay="" if ok else f"perf_report.json 里有 {len(kept)} 个保留的改动（{kept}），但 v0 之后只有 {commits} 个提交；每个保留的改动都要单独提交。")


